-- READ ONLY. Confirm original project pmzbdrxedlthdqdpgigs manually; never M4E.
-- Run as project owner. Return check labels only, no identities or records.
with checks(check_name,ok) as(values
 ('nigraan_claim_judge_email',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_claim_judge_email' and p.oid=to_regprocedure('public.nigraan_claim_judge_email(uuid)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='e38abd5a4abd51e38af5a2f60f5310b6')),false)),
 ('nigraan_retry_judge_email',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_retry_judge_email' and p.oid=to_regprocedure('public.nigraan_retry_judge_email(uuid)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='2ea81ae9fc6d0aa5f980c3a6e8eb10ec')),false)),
 ('is_approved_operations',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='is_approved_operations' and p.oid=to_regprocedure('public.is_approved_operations()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='e1fbe6f682f94c1b21c21ed5567dc0f5')),false)),
 ('nigraan_is_judge_admin',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_is_judge_admin' and p.oid=to_regprocedure('public.nigraan_is_judge_admin()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='1ac725896b70e5e9c83e2ed6ed3a3890')),false)),
 ('nigraan_is_permanent_operations',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_is_permanent_operations' and p.oid=to_regprocedure('public.nigraan_is_permanent_operations()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='f73ad124cf7222569038b63d7f7937f0')),false)),
 ('nigraan_has_operations_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_has_operations_access' and p.oid=to_regprocedure('public.nigraan_has_operations_access()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='f5b6d2c65158b5bfdae6034edca3095e')),false)),
 ('nigraan_operations_access_context',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_operations_access_context' and p.oid=to_regprocedure('public.nigraan_operations_access_context()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='0b705106d3e9bff338203fa4e6a06cca')),false)),
 ('nigraan_decide_judge_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_decide_judge_access' and p.oid=to_regprocedure('public.nigraan_decide_judge_access(uuid,text)') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='664ca187390c4f9eb1363269227bd409')),false)),
 ('nigraan_list_judge_requests',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_list_judge_requests' and p.oid=to_regprocedure('public.nigraan_list_judge_requests()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='6fdadc9e6985e57420155e83d9e81cea')),false)),
 ('nigraan_activate_judge_access',coalesce(((select count(*)=1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='nigraan_activate_judge_access' and p.oid=to_regprocedure('public.nigraan_activate_judge_access()') and p.proconfig @> array['search_path=""'] and p.prosecdef and md5(trim(regexp_replace(p.prosrc,'\s+',' ','g')))='6d63fe7e2bd4c92b698a78312850e1c9')),false)),
 ('private_tables',coalesce(((select count(*)=4 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('nigraan_judge_admins','nigraan_judge_requests','nigraan_judge_audit','nigraan_judge_email_outbox'))),false)),
 ('no_direct_authenticated_writes',coalesce((not exists(select 1 from information_schema.role_table_grants where table_schema='public' and table_name in('nigraan_judge_admins','nigraan_judge_requests','nigraan_judge_audit','nigraan_judge_email_outbox') and grantee in('authenticated','anon','service_role','PUBLIC') and privilege_type in('INSERT','UPDATE','DELETE'))),false)),
 ('020_not_applied',coalesce((not exists(select 1 from information_schema.columns where table_schema='public' and table_name='nigraan_judge_requests' and column_name='cycle')),false))
) select case when bool_and(ok) then 'PASS' else 'BLOCKED' end verdict, count(*) filter(where not ok) blocked_checks,coalesce(jsonb_agg(check_name) filter(where not ok),'[]'::jsonb) mismatches from checks;
